                     &&& 0 <= i < self.bitmap@.num_bits
                     &&& !#[trigger] self.bitmap@.set_bits.contains(i)
                     &&& addr == frame_addr_of(i)
                 }
             ),
             refcounts: Map::new(
                 |addr: int|
                     exists|i: int|
